for (const s of SCROLLS) {
  add({
    id: s.id,
    name: s.name,
    type: 'use',
    price: s.price ?? 0,
    scroll: { slots: s.slots, chance: s.chance, stats: s.stats },
    color: s.chance >= 1 ? '#bff0dc' : s.chance >= 0.6 ? '#8fd3ff' : '#ff9ec0',
    desc: `Use on ${s.slots.join('/')}. ${Math.round(s.chance * 100)}% success.`,
  });
}

